// Get employee API response
const employeeResponse = $('Access360 - Get Employees').first().json.response;

// Get attendance API response
const attendanceResponse = $('Access360 - Get Attendance Data').first().json.response;


// --------------------------------------------------
// 1. Build Employee ID → Employee Name mapping
// --------------------------------------------------

const employeeMap = {};

for (const emp of employeeResponse) {

  if (emp.empID) {
    employeeMap[String(emp.empID).trim()] = emp.empName || null;
  }

}


// --------------------------------------------------
// 2. Process attendance records
// --------------------------------------------------

const result = [];

for (const attendance of attendanceResponse) {

  const employeeId = String(
    attendance.employeeId || ''
  ).trim();

  result.push({
    json: {
      employeeId: employeeId,

      employeeName: employeeMap[employeeId] || null,

      eventType: attendance.eventType || null,

      eventTime: attendance.eventTime || null,

      branchName: attendance.branchName || null,

      sourceId: attendance.id || null
    }
  });

}


return result;

