const records = $input.all();

function formatIST(timestamp) {
  if (!timestamp) return null;

  // Keep the date/time exactly as received.
  // Only change the timezone suffix.
  return timestamp
    .replace(/\+00:00$/, '+05:30')
    .replace(/Z$/, '+05:30');
}

const attendances = [];
const sourceRecords = [];

for (const item of records) {
  const data = item.json;

  const eventTime = formatIST(data.event_time);

  // This is what will be sent to the destination API
  attendances.push({
    org_user_id: String(data.employee_id || '').trim(),

    punched_in_at:
      data.event_type?.toLowerCase() === 'login'
        ? eventTime
        : null,

    punched_out_at:
      data.event_type?.toLowerCase() === 'logout'
        ? eventTime
        : null
  });

  // Keep the original Access360 information inside n8n
  // so we can use it later for PostgreSQL logging.
  sourceRecords.push({
    access360_id: data.access360_id,
    employee_id: data.employee_id,
    event_type: data.event_type,
    event_time: eventTime
  });
}

// Return ONE n8n item
return [
  {
    json: {
      attendances: attendances,
      source_records: sourceRecords
    }
  }
];

parameters.query:
SELECT
    {{ $json.access360_id }} AS access360_id,
    '{{ String($json.employee_id ?? '').replace(/'/g, "''") }}' AS employee_id,
    '{{ String($json.event_type ?? '').replace(/'/g, "''") }}' AS event_type,
    '{{ $json.event_time }}' AS event_time,
    EXISTS (
        SELECT 1
        FROM access360_processed_attendance_noida
        WHERE access360_id = {{ $json.access360_id }}
    ) AS already_processed;

