// Get the batch API response
const responseItems = $input.all();

if (responseItems.length === 0) {
  return [];
}

// Get the original batch data from Prepare Attendance Payload
const payloadItems = $('Prepare Attendance Payload').all();

if (payloadItems.length === 0) {
  throw new Error('No data found from Prepare Attendance Payload');
}

const payload = payloadItems[0].json;

const sourceRecords = payload.source_records || [];
const attendances = payload.attendances || [];

// Get all results returned by the destination API
const results = responseItems.flatMap(item => {
  return Array.isArray(item.json.results)
    ? item.json.results
    : [];
});

const output = [];

// Match API results back to the original records
for (const result of results) {

  // Only process successful records
  if (String(result.status || '').toLowerCase() !== 'success') {
    continue;
  }

  const orgUserId = String(result.org_user_id || '').trim();

  // Find the original record using employee/org_user_id
  const matchingIndexes = [];

  for (let i = 0; i < attendances.length; i++) {
    if (
      String(attendances[i].org_user_id || '').trim() === orgUserId
    ) {
      matchingIndexes.push(i);
    }
  }

  if (matchingIndexes.length === 0) {
    continue;
  }

  // Find an original record that has not already been mapped
  let matchedIndex = null;

  for (const index of matchingIndexes) {
    const alreadyUsed = output.some(
      item =>
        item.json.access360_id === sourceRecords[index]?.access360_id
    );

    if (!alreadyUsed) {
      matchedIndex = index;
      break;
    }
  }

  if (matchedIndex === null) {
    continue;
  }

  const original = sourceRecords[matchedIndex];

  output.push({
    json: {
      access360_id: original.access360_id,
      employee_id: original.employee_id,
      event_type: original.event_type,
      event_time: original.event_time,
      destination_attendance_id: result.attendance_id
    }
  });
}

return output;

